const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
let maxRight = -Infinity;
let invisible = 0;

for (let i = n; i >= 1; i--) {
  const height = input[i];
  if (height <= maxRight) invisible++;
  if (height > maxRight) maxRight = height;
}

console.log(invisible);
